import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: OTP는 숫자 6자리 형식으로 검사한다.
const OTP_PATTERN = /^[0-9]{6}$/;
const LOGIN_TYPES = ['웹', '메신저', '모바일'];

interface Failure {
  status: number;
  code: string;
  message: string;
}

@Controller('api/v1')
export class FnSfr03701Controller {
  @Post('/auth/second-factor/verify')
  @HttpCode(200)
  async verifySecondAuth(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const loginType = data['loginType'];
    const otpCode = data['otpCode'];
    const deviceIdentifier = data['deviceIdentifier'];
    if (typeof loginType !== 'string' || !LOGIN_TYPES.includes(loginType)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '로그인 구분은 웹, 메신저, 모바일 중 하나여야 합니다.');
    }
    if (typeof otpCode !== 'string' || !OTP_PATTERN.test(otpCode)) {
      throw new ApiError(400, 'VALIDATION_FAILED', 'OTP 인증번호를 숫자 6자리로 입력해 주세요.');
    }
    if (deviceIdentifier !== undefined && deviceIdentifier !== null && deviceIdentifier !== '') {
      if (typeof deviceIdentifier !== 'string' || deviceIdentifier.length > 200) {
        throw new ApiError(400, 'VALIDATION_FAILED', '인증기기 식별값은 200자 이하의 글자여야 합니다.');
      }
    }
    const device = typeof deviceIdentifier === 'string' && deviceIdentifier !== '' ? deviceIdentifier : null;
    const loginIp = String(req.ip ?? '0.0.0.0').slice(0, 45);

    const outcome = await transaction(async (db) => {
      const devices = await db.query(
        'SELECT device_identifier, status FROM auth_device WHERE employee_id = CAST(:userId AS bigint)',
        { userId: user.id },
      );
      const approved = devices.filter((d: any) => d.status === '승인');
      let failure: Failure | null = null;
      if (approved.length === 0) {
        const hasOther = device !== null && devices.some((d: any) => d.device_identifier === device);
        if (hasOther) {
          failure = { status: 409, code: 'AUTH_DEVICE_NOT_APPROVED', message: '미승인·반려·해제된 인증기기로는 인증할 수 없습니다.' };
        } else {
          failure = { status: 422, code: 'APPROVED_DEVICE_REQUIRED', message: '승인된 인증기기가 없습니다. 인증기기를 등록하고 승인을 받아 주세요.' };
        }
      } else if (device !== null && !approved.some((d: any) => d.device_identifier === device)) {
        failure = { status: 409, code: 'AUTH_DEVICE_NOT_APPROVED', message: '미승인·반려·해제된 인증기기로는 인증할 수 없습니다.' };
      }
      // TODO: OTP 일치·유효시간 검증은 입력에 OTP 비밀값·알고리즘 출처가 없어 형식 검사만 한다 (todos 참고).
      const result = failure === null ? '성공' : '실패';
      await db.query(
        'INSERT INTO access_log (employee_id, event_type, accessed_at, login_ip, login_type, second_auth_result, created_at, updated_at) VALUES (CAST(:userId AS bigint), :eventType, now(), :loginIp, :loginType, :result, now(), now()) RETURNING access_log_id',
        { userId: user.id, eventType: '로그인', loginIp, loginType, result },
      );
      return { failure, result };
    });

    // 실패 이력이 되돌려지지 않도록 트랜잭션이 끝난 뒤에 오류를 던진다.
    if (outcome.failure !== null) {
      throw new ApiError(outcome.failure.status, outcome.failure.code, outcome.failure.message);
    }
    return {
      authResult: '2차 인증에 성공하여 로그인이 허용되었습니다.',
      secondAuthResult: outcome.result,
    };
  }
}

