import { useState } from 'react';
import { ApiFail, Badge, Band, DataTable, DateText, Drawer, Field, Form, Select, Tiles, TextInput, call } from '../kit';
import type { PageProps, Row } from '../kit';

const LOGIN_TYPES: [string, string][] = [
  ['웹', '웹'],
  ['메신저', '메신저'],
  ['모바일', '모바일'],
];

export default function FnSfr03701Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [loginType, setLoginType] = useState('');
  const [otpCode, setOtpCode] = useState('');
  const [deviceIdentifier, setDeviceIdentifier] = useState('');
  const [history, setHistory] = useState<Row[]>([]);

  const successCount = history.filter((h) => h.result === '성공').length;
  const failCount = history.filter((h) => h.result === '실패').length;

  function record(result: string, message: string) {
    setHistory((prev) => [
      { id: prev.length + 1, at: new Date().toISOString(), loginType, result, message },
      ...prev,
    ]);
  }

  function openDrawer() {
    setLoginType('');
    setOtpCode('');
    setDeviceIdentifier('');
    setOpen(true);
  }

  async function submit() {
    if (!loginType) {
      throw new Error('로그인 경로를 선택해 주세요.');
    }
    if (!otpCode.trim()) {
      throw new Error('OTP 인증번호를 입력해 주세요.');
    }
    try {
      const res = await call('POST', '/auth/second-factor/verify', role, {
        loginType,
        otpCode: otpCode.trim(),
        deviceIdentifier: deviceIdentifier.trim() || undefined,
      });
      record(String(res.secondAuthResult ?? '성공'), String(res.authResult ?? ''));
      notify('2차 인증을 완료했습니다.');
      setOpen(false);
    } catch (e) {
      if (e instanceof ApiFail) {
        record('실패', e.message);
      }
      throw e;
    }
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>인증 현황</h2>
        <Tiles
          items={[
            ['이번 접속 성공', successCount],
            ['이번 접속 실패', failCount],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>인증 결과</h2>
        <Band total={history.length}>
          <button type="button" onClick={openDrawer}>2차 인증</button>
        </Band>
        <DataTable
          rows={history}
          empty="이 화면에서 처리한 인증 결과가 없습니다."
          columns={[
            { key: 'at', label: '인증 일시', render: (r) => <DateText value={r.at} time /> },
            { key: 'loginType', label: '로그인 구분' },
            { key: 'result', label: '2차 인증 결과', render: (r) => <Badge value={r.result} /> },
            { key: 'message', label: '안내' },
          ]}
        />
      </section>
      {open && (
        <Drawer title="2차 인증 로그인" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="인증">
            <Field label="로그인 구분" required>
              <Select value={loginType} onChange={setLoginType} options={LOGIN_TYPES} />
            </Field>
            <Field label="OTP 인증번호" required hint="인증기기에서 확인한 일회용 번호 6자리">
              <TextInput value={otpCode} onChange={setOtpCode} />
            </Field>
            <Field label="인증기기 식별값">
              <TextInput value={deviceIdentifier} onChange={setDeviceIdentifier} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
